#include <zephyr/device.h>
#include <zephyr/devicetree.h>
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/espi.h>
#include <zephyr/drivers/espi_emul.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(espi_emul, CONFIG_ESPI_LOG_LEVEL);

/**
 * @brief eSPI emulator data
 *
 * @param emuls List of emulators for eSPI peripherals.
 * @param emuls_cnt Number of emulators.
 */
struct espi_emul_data {
	const struct device **emuls;
	int emuls_cnt;
};

static int espi_emul_config(const struct device *dev, struct espi_cfg *cfg)
{
	/* Not supported by emulator */
	return -ENOTSUP;
}

static bool espi_emul_get_channel_status(const struct device *dev, enum espi_channel ch)
{
	/* Channels are always ready */
	return true;
}

static int espi_emul_send_vwire(const struct device *dev, enum espi_vwire_signal signal,
			      uint8_t level)
{
	struct espi_emul_data *data = dev->data;

	for (int i = 0; i < data->emuls_cnt; i++) {
		espi_emul_send_vwire_to_backend(data->emuls[i], signal, level);
	}

	return 0;
}

static int espi_emul_receive_vwire(const struct device *dev, enum espi_vwire_signal signal,
				 uint8_t *level)
{
	struct espi_emul_data *data = dev->data;

	/*
	 * Return value from first backend that returns success. This is
	 * required because only one peripheral can drive signal at a time.
	 */
	for (int i = 0; i < data->emuls_cnt; i++) {
		if (espi_emul_receive_vwire_from_backend(data->emuls[i], signal,
							 level) == 0) {
			return 0;
		}
	}

	return -EIO;
}

static int espi_emul_send_oob(const struct device *dev, struct espi_oob_packet *p)
{
	struct espi_emul_data *data = dev->data;

	for (int i = 0; i < data->emuls_cnt; i++) {
		espi_emul_send_oob_to_backend(data->emuls[i], p);
	}

	return 0;
}

static int espi_emul_receive_oob(const struct device *dev, struct espi_oob_packet *p)
{
	struct espi_emul_data *data = dev->data;

	/* Return value from first backend that returns success */
	for (int i = 0; i < data->emuls_cnt; i++) {
		if (espi_emul_receive_oob_from_backend(data->emuls[i], p) == 0) {
			return 0;
		}
	}

	return -EIO;
}

static int espi_emul_read_lpc_request(const struct device *dev, enum lpc_cyc_type type,
				    uint32_t *data)
{
	/* Not supported by emulator */
	return -ENOTSUP;
}

static int espi_emul_write_lpc_response(const struct device *dev, enum lpc_cyc_type type,
				      uint32_t data)
{
	/* Not supported by emulator */
	return -ENOTSUP;
}

static int espi_emul_acpi_read(const struct device *dev, uint8_t *p_type, uint32_t *addr,
			     uint8_t *len)
{
	/* Not supported by emulator */
	return -ENOTSUP;
}

#define ESPI_EMUL_CHILD_EMUL_GET(inst, node_id) \
	COND_CODE_1(DT_EMUL_ENABLED(node_id), (EMUL_DT_GET(node_id),), ())

#define ESPI_EMUL_INIT(n) \
	static int espi_emul_init_##n(const struct device *dev) \
	{ \
		struct espi_emul_data *data = dev->data; \
		static const struct device *emuls[] = { \
			DT_INST_FOREACH_CHILD_STATUS_OKAY(n, ESPI_EMUL_CHILD_EMUL_GET) \
		}; \
		data->emuls = emuls; \
		data->emuls_cnt = ARRAY_SIZE(emuls); \
		return 0; \
	} \
	\
	static struct espi_emul_data espi_emul_data_##n; \
	\
	static const struct espi_driver_api espi_emul_api_##n = { \
		.config = espi_emul_config, \
		.get_channel_status = espi_emul_get_channel_status, \
		.send_vwire = espi_emul_send_vwire, \
		.receive_vwire = espi_emul_receive_vwire, \
		.send_oob = espi_emul_send_oob, \
		.receive_oob = espi_emul_receive_oob, \
		.read_lpc_request = espi_emul_read_lpc_request, \
		.write_lpc_response = espi_emul_write_lpc_response, \
		.acpi_read = espi_emul_acpi_read, \
	}; \
	\
	DEVICE_DT_INST_DEFINE(n, espi_emul_init_##n, NULL, \
			      &espi_emul_data_##n, NULL, POST_KERNEL, \
			      CONFIG_ESPI_INIT_PRIORITY, &espi_emul_api_##n);

DT_INST_FOREACH_STATUS_OKAY(ESPI_EMUL_INIT)
